import json
import numpy as np
from sympy import symbols, SOPform

# Find the public truth table already loaded in the sandbox.
def find_table(obj, seen=None):
    if seen is None:
        seen = set()
    if id(obj) in seen:
        return None
    seen.add(id(obj))
    if isinstance(obj, dict):
        if (isinstance(obj.get("inputs"), list)
                and len(obj["inputs"]) == 1024
                and isinstance(obj.get("outputs"), list)
                and len(obj["outputs"]) == 1024):
            return obj["inputs"], obj["outputs"]
        for v in obj.values():
            found = find_table(v, seen)
            if found:
                return found
    elif isinstance(obj, (list, tuple)):
        for v in obj:
            found = find_table(v, seen)
            if found:
                return found
    return None

table = None
for name, value in list(globals().items()):
    if not name.startswith("_"):
        table = find_table(value)
        if table:
            break
if table is None:
    raise RuntimeError("Could not locate the public 1024-row truth table.")

inputs, outputs = table
xs = symbols("x0:10")
ones = [tuple(map(int, row)) for row, y in zip(inputs, outputs) if int(y)]
expr = SOPform(xs, ones)

# The target table is a composed Boolean circuit. Build a truth-table
# expression and check that its gate schedule fits the fixed network.
from sympy.logic.boolalg import And, Or, Not, Xor, BooleanTrue, BooleanFalse

gates = []
def compile_expr(e):
    if e in xs:
        return ("input", xs.index(e))
    if e is BooleanTrue:
        return ("const", 1)
    if e is BooleanFalse:
        return ("const", 0)
    if isinstance(e, Not):
        return ("not", compile_expr(e.args[0]))
    if isinstance(e, (And, Or, Xor)):
        op = "and" if isinstance(e, And) else "or" if isinstance(e, Or) else "xor"
        args = [compile_expr(a) for a in e.args]
        cur = args[0]
        for arg in args[1:]:
            gates.append((op, cur, arg))
            cur = ("gate", len(gates) - 1)
        return cur
    raise ValueError(f"Unsupported Boolean expression: {e}")

root = compile_expr(expr)
if root[0] != "gate":
    gates.append(("buf", root, None))
    root = ("gate", len(gates) - 1)

# Schedule gates by dependency depth; each hidden layer has eight
# logical signal slots (channels 10,13,...,31).
depth = [0] * len(gates)
for i, (op, a, b) in enumerate(gates):
    deps = [v[1] for v in (a, b) if v is not None and v[0] == "gate"]
    depth[i] = 1 + max((depth[j] for j in deps), default=0)
layers = {}
for i, d in enumerate(depth):
    layers.setdefault(d, []).append(i)
if max(layers) > 4 or any(len(v) > 8 for v in layers.values()):
    raise RuntimeError("The minimized circuit does not fit the four-stage, eight-slot layout.")

