# channel of its triple; the remaining channels are zero.
def source(v, stage):
    if v[0] == "input":
        return v[1]
    if v[0] == "const":
        return None
    j = v[1]
    return 10 + 3 * (layers[depth[j]].index(j))

# Copy the ten original inputs through all four stages.
for stage, wt in enumerate(("w0", "w1", "w2", "w3")):
    for i in range(10):
        put(wt, [i, i], 1)
    for i in range(8):
        for k in range(3):
            put(wt, [10 + 3*i + k, :], 0)

# Construct stage weights and biases from the analytic gate list.
for stage, (wt, bt) in enumerate(zip(("w0", "w1", "w2", "w3"),
                                     ("b0", "b1", "b2", "b3")), 1):
    for gi in layers.get(stage, []):
        slot = layers[stage].index(gi)
        row = 10 + 3 * slot
        op, a, b = gates[gi]
        refs = [a] if op in ("not", "buf") else [a, b]
        coeff, bias = {}, 0.0
        for v in refs:
            if v[0] == "const":
                bias += v[1]
            elif v[0] == "input":
                coeff[v[1]] = coeff.get(v[1], 0) + 1
            else:
                prev = v[1]
                coeff[10 + 3 * layers[depth[prev]].index(prev)] = (
                    coeff.get(10 + 3 * layers[depth[prev]].index(prev), 0) + 1
                )
        if op == "not":
            coeff = {k: -v for k, v in coeff.items()}
            bias += 0.5
        elif op == "and":
            bias -= len(refs) - 0.5
        elif op == "or":
            bias -= 0.5
        elif op == "xor":
            raise RuntimeError("XOR needs decomposition into AND/OR/NOT gates.")
        elif op == "buf":
            bias -= 0.5
        for col, val in coeff.items():
            put(wt, [row, col], val)
        put(bt, [row], bias)

# Final class-1 logit is the root signal; class 0 wins when it is false.
root_gate = root[1]
root_channel = 10 + 3 * layers[depth[root_gate]].index(root_gate)
put("out", [1, root_channel], 1)
put("out", [0, root_channel], 0)
